    INSERT INTO authz_sync."folder__mirror" SELECT x.* FROM (SELECT mr.* FROM "app"."folders" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."folder__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."folder__readers" r WHERE r."id" = f."id"))) mr) x WHERE NOT EXISTS (SELECT 1 FROM authz_sync."folder__mirror" m WHERE m::text = x::text);
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k WHERE k.conrelid = 'authz_sync."folder__mirror"'::regclass AND k.contype = 'p') THEN
      ALTER TABLE authz_sync."folder__mirror" ADD PRIMARY KEY ("id");
