    INSERT INTO authz_sync."folder__mirror" SELECT mr.* FROM "app"."folders" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."folder__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."folder__readers" r WHERE r."id" = f."id"))) mr;
  END IF;
END $mi$;
-- PowerSync's mirror of app.notes (mirrored): every column of the table but those the policy masks, and readers, a
-- JSON array of the keys that may read the row, which a stream's buckets are keyed by. Kept across applies; changed
-- in place when the table's columns changed (so the publication that holds it keeps it)
-- @object table authz_sync."note__mirror"
DO $mi$
DECLARE c name; ty text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = '"app"."notes"'::regclass AND a.attname = 'readers'
             AND a.attnum > 0 AND NOT a.attisdropped) THEN
    RAISE EXCEPTION 'app.notes has a column readers, which its mirror keeps each row''s keys in [AZ811]'
      USING HINT = 'rename the column, or sync the table without mirrored: rowstile help AZ811';
  END IF;
  IF to_regclass('authz_sync."note__mirror"') IS NOT NULL AND NOT coalesce((SELECT pg_catalog.array_agg(a.attname || ' ' || pg_catalog.format_type(a.atttypid, a.atttypmod) ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = to_regclass('authz_sync."note__mirror"') AND a.attnum > 0 AND NOT a.attisdropped AND a.attname <> ALL (ARRAY['readers']::name[])) = (SELECT pg_catalog.array_agg(a.attname || ' ' || pg_catalog.format_type(a.atttypid, a.atttypmod) ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = to_regclass('"app"."notes"') AND a.attnum > 0 AND NOT a.attisdropped AND a.attname <> ALL (ARRAY['body']::name[])), false) THEN
    -- its columns that aren't the table's (dropped there, masked since, or of another type there) go, and those it
    -- lacks are added (a key column among them takes the primary key with it: made again below) ...
    FOR c IN SELECT a.attname FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'authz_sync."note__mirror"'::regclass AND a.attnum > 0
               AND NOT a.attisdropped AND a.attname <> 'readers' AND NOT EXISTS (
                 SELECT 1 FROM pg_catalog.pg_attribute b WHERE b.attrelid = '"app"."notes"'::regclass AND b.attnum > 0
                 AND NOT b.attisdropped AND b.attname = a.attname AND b.atttypid = a.atttypid AND b.atttypmod = a.atttypmod
                 AND b.attname <> ALL (ARRAY['body']::name[])) LOOP
      EXECUTE pg_catalog.format('ALTER TABLE %s DROP COLUMN %I', 'authz_sync."note__mirror"', c);
    END LOOP;
    FOR c, ty IN SELECT b.attname, pg_catalog.format_type(b.atttypid, b.atttypmod) FROM pg_catalog.pg_attribute b
                 WHERE b.attrelid = '"app"."notes"'::regclass AND b.attnum > 0 AND NOT b.attisdropped AND b.attname <> ALL (ARRAY['body']::name[])
                 AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'authz_sync."note__mirror"'::regclass
                                 AND a.attname = b.attname AND a.attnum > 0 AND NOT a.attisdropped) ORDER BY b.attnum LOOP
      EXECUTE pg_catalog.format('ALTER TABLE %s ADD COLUMN %I %s', 'authz_sync."note__mirror"', c, ty);
    END LOOP;
    -- ... then its rows are written again where they differ
    DELETE FROM authz_sync."note__mirror" m WHERE NOT EXISTS (SELECT 1 FROM (SELECT mr.* FROM "app"."notes" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."note__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."note__readers" r WHERE r."id" = f."id"))) mr) x WHERE x::text = m::text);
    INSERT INTO authz_sync."note__mirror" SELECT x.* FROM (SELECT mr.* FROM "app"."notes" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."note__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."note__readers" r WHERE r."id" = f."id"))) mr) x WHERE NOT EXISTS (SELECT 1 FROM authz_sync."note__mirror" m WHERE m::text = x::text);
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k WHERE k.conrelid = 'authz_sync."note__mirror"'::regclass AND k.contype = 'p') THEN
      ALTER TABLE authz_sync."note__mirror" ADD PRIMARY KEY ("id");
    END IF;
  END IF;
  IF to_regclass('authz_sync."note__mirror"') IS NULL THEN
    CREATE TABLE authz_sync."note__mirror" (LIKE "app"."notes");
    ALTER TABLE authz_sync."note__mirror" DROP COLUMN "body";
    -- (any column may be NULL but the key's: one dropped from the table since gives its rows NULL, not an error)
    FOR c IN SELECT a.attname FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'authz_sync."note__mirror"'::regclass AND a.attnum > 0
               AND NOT a.attisdropped AND a.attnotnull AND a.attname <> ALL (ARRAY['id']::name[]) LOOP
      EXECUTE pg_catalog.format('ALTER TABLE %s ALTER COLUMN %I DROP NOT NULL', 'authz_sync."note__mirror"', c);
    END LOOP;
    ALTER TABLE authz_sync."note__mirror" ADD COLUMN readers text NOT NULL DEFAULT '[]', ADD PRIMARY KEY ("id"), REPLICA IDENTITY FULL;
    INSERT INTO authz_sync."note__mirror" SELECT mr.* FROM "app"."notes" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."note__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."note__readers" r WHERE r."id" = f."id"))) mr;
  END IF;
END $mi$;
REVOKE ALL ON ALL TABLES IN SCHEMA authz_sync FROM PUBLIC;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

CREATE OR REPLACE FUNCTION authz_int."file__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('file', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."folder_id" IS DISTINCT FROM o."folder_id" OR n."owner_id" IS DISTINCT FROM o."owner_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n.*)) e WHERE lower(e.key) = ANY (ARRAY['confidential'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o.*)) e WHERE lower(e.key) = ANY (ARRAY['confidential']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', n."id"::text, 'folder', n."folder_id"::text, jsonb_build_object('column', 'folder_id', 'was', o."folder_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."folder_id" IS DISTINCT FROM o."folder_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = n."id"::text AND a.relation = 'folder' AND a.detail->>'column' = 'folder_id'
          AND a.subject_id IS NOT DISTINCT FROM n."folder_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."folder_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', n."id"::text, 'owner', n."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', o."owner_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."owner_id" IS DISTINCT FROM o."owner_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = n."id"::text AND a.relation = 'owner' AND a.detail->>'column' = 'owner_id'
          AND a.subject_id IS NOT DISTINCT FROM n."owner_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."owner_id"));
    END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.notes:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."notes"; r_new "app"."notes";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for app.notes: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.notes', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT (jsonb_populate_record(NULL::"app"."notes", to_jsonb(x.*))).* INTO r_old FROM "app"."notes_visible" x WHERE x."id" = p_id::integer;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.notes: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for app.notes: nobody may update its rows'];
END $f$;

-- checked on the row after the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own; before the update, or after it where the table has a generated column
-- @object trigger "authz_update_after parent_id" ON "app"."folders"
DO $tr$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = '"app"."folders"'::pg_catalog.regclass
             AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated <> '') THEN
    EXECUTE 'CREATE TRIGGER "authz_update_after parent_id" AFTER UPDATE ON "app"."folders" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active(''"app"."folders"''::pg_catalog.regclass)
    AND NOT authz_int."app.folders:column parent_id after:holds"(pg_catalog.to_jsonb(NEW.*), current_user))
  EXECUTE FUNCTION authz_int."app.folders:column parent_id after"()';
  ELSE
    EXECUTE 'CREATE TRIGGER "authz_update_after parent_id" BEFORE UPDATE ON "app"."folders" FOR EACH ROW
  WHEN ((OLD."parent_id" IS DISTINCT FROM NEW."parent_id")
    AND pg_catalog.row_security_active(''"app"."folders"''::pg_catalog.regclass)
    AND NOT authz_int."app.folders:column parent_id after:holds"(pg_catalog.to_jsonb(NEW.*), current_user))
  EXECUTE FUNCTION authz_int."app.folders:column parent_id after"()';
  END IF;
END $tr$;

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. Where the rule's trigger runs after the update, the rule is
-- asked again when the statement is done, of each row it left with other values in these columns than the row that
-- had its key (a key the update made: than the one key it left without a row, or, where that isn't one for one,
-- whatever changed). A trigger before the update has asked it of every row already
CREATE OR REPLACE FUNCTION authz_int."app.folders:column parent_id after:moved"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "app"."folders"; v_one boolean; v_virtual text;
BEGIN
  IF NOT pg_catalog.row_security_active('"app"."folders"'::pg_catalog.regclass) THEN RETURN NULL; END IF;
  -- (tgtype's bit 2: before. Asked unless a trigger before the update is there, and on: without one, never less)
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_trigger g WHERE g.tgrelid = '"app"."folders"'::pg_catalog.regclass AND g.tgname = 'authz_update_after parent_id'
             AND g.tgtype & 2 <> 0 AND g.tgenabled <> 'D') THEN
    RETURN NULL;
  END IF;
  -- (PostgreSQL 18: each row with its virtual generated columns, which the statement's rows don't hold)
  SELECT pg_catalog.string_agg(pg_catalog.format('%L, (%s)', a.attname, pg_catalog.pg_get_expr(d.adbin, d.adrelid)), ', ')
      INTO v_virtual FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = '"app"."folders"'::pg_catalog.regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated = 'v';
  v_one := (SELECT count(*) FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)) = 1
       AND (SELECT count(*) FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)) = 1;
  FOR v_row IN
    SELECT (pg_catalog.jsonb_populate_record(NULL::"app"."folders", pg_catalog.to_jsonb(n.*))).* FROM new_rows n
    WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text AND o."parent_id" IS NOT DISTINCT FROM n."parent_id")
      AND NOT (v_one AND NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
               AND EXISTS (SELECT 1 FROM old_rows o WHERE o."parent_id" IS NOT DISTINCT FROM n."parent_id"
                           AND NOT EXISTS (SELECT 1 FROM new_rows m WHERE m."id"::text = o."id"::text)))
  LOOP
    IF v_virtual IS NOT NULL THEN
      EXECUTE 'SELECT (pg_catalog.jsonb_populate_record($1, pg_catalog.jsonb_build_object(' || v_virtual
        || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
    END IF;
    IF NOT (authz_gen."app.folders:column parent_id after:items"(v_row, current_user))[1] THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.folders:column parent_id after:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing parent_id of app.folders % needs: parent.edit', v_row."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'app', TABLE = 'folders', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END LOOP;
  RETURN NULL;
END $f$;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update owner_id" BEFORE UPDATE ON "app"."files" FOR EACH ROW
  WHEN ((OLD."owner_id" IS DISTINCT FROM NEW."owner_id")
    AND pg_catalog.row_security_active('"app"."files"'::pg_catalog.regclass)
    AND NOT authz_int."app.files:column owner_id:holds"(pg_catalog.to_jsonb(OLD.*), current_user))
  EXECUTE FUNCTION authz_int."app.files:column owner_id"();

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- the index worked out again where what it is worked out by changed (p_hash), or all of it (p_force); by difference
CREATE OR REPLACE FUNCTION authz_int.sync_refresh(p_hash text, p_force boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF p_force OR NOT EXISTS (SELECT 1 FROM authz_sync.definitions d WHERE d.name = 'index' AND d.hash = p_hash) THEN
    -- what this policy no longer keeps
  DELETE FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) <> ALL (ARRAY['team#member:']::text[]);
    DELETE FROM authz_sync.keys k WHERE k.principal_type <> ALL (ARRAY['user']::text[]);
    DELETE FROM authz_sync.expanded x WHERE x.object_type <> ALL (ARRAY['file', 'folder', 'note']::text[]);
    DELETE FROM authz_sync.due d WHERE d.object_type <> ALL (ARRAY['file', 'folder', 'note', 'team', 'user']::text[]);
    INSERT INTO authz_int.sync_todo (txid, type, id) SELECT txid_current(), x, '*' FROM unnest(ARRAY['file', 'folder', 'note', 'team', 'user']::text[]) x ON CONFLICT DO NOTHING;
  END IF;
  PERFORM authz_int.sync_process();
  IF p_force THEN
    DELETE FROM authz_sync."file__mirror" m WHERE NOT EXISTS (SELECT 1 FROM (SELECT mr.* FROM "app"."files" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."file__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."file__readers" r WHERE r."id" = f."id"))) mr) x
                                                           WHERE x::text = m::text);
    INSERT INTO authz_sync."file__mirror" SELECT x.* FROM (SELECT mr.* FROM "app"."files" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."file__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."file__readers" r WHERE r."id" = f."id"))) mr) x
      WHERE NOT EXISTS (SELECT 1 FROM authz_sync."file__mirror" m WHERE m::text = x::text);
  END IF;
  IF p_force THEN
    DELETE FROM authz_sync."folder__mirror" m WHERE NOT EXISTS (SELECT 1 FROM (SELECT mr.* FROM "app"."folders" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."folder__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."folder__readers" r WHERE r."id" = f."id"))) mr) x
                                                           WHERE x::text = m::text);
    INSERT INTO authz_sync."folder__mirror" SELECT x.* FROM (SELECT mr.* FROM "app"."folders" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."folder__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."folder__readers" r WHERE r."id" = f."id"))) mr) x
      WHERE NOT EXISTS (SELECT 1 FROM authz_sync."folder__mirror" m WHERE m::text = x::text);
  END IF;
  IF p_force THEN
    DELETE FROM authz_sync."note__mirror" m WHERE NOT EXISTS (SELECT 1 FROM (SELECT mr.* FROM "app"."notes" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."note__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."note__readers" r WHERE r."id" = f."id"))) mr) x
                                                           WHERE x::text = m::text);
    INSERT INTO authz_sync."note__mirror" SELECT x.* FROM (SELECT mr.* FROM "app"."notes" f CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."note__mirror", pg_catalog.to_jsonb(f.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."note__readers" r WHERE r."id" = f."id"))) mr) x
      WHERE NOT EXISTS (SELECT 1 FROM authz_sync."note__mirror" m WHERE m::text = x::text);
  END IF;
  IF p_hash IS NOT NULL THEN
    INSERT INTO authz_sync.definitions VALUES ('index', p_hash) ON CONFLICT (name) DO UPDATE SET hash = EXCLUDED.hash;
  END IF;
END $f$;

-- PowerSync's mirror of app.files, kept as its rows are written ...
CREATE OR REPLACE FUNCTION authz_int."file__mirror"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' AND TG_RELID = '"app"."files"'::regclass THEN
    DELETE FROM authz_sync."file__mirror";
    RETURN NULL;
  ELSIF TG_OP = 'TRUNCATE' THEN
    -- a partition emptied, or a table that inherits (this trigger is on each of them too, CHILD_TRIGGERS): the rows
    -- stored there leave the mirror, and the type's readers are worked out again
    DELETE FROM authz_sync."file__mirror" m WHERE NOT EXISTS (SELECT 1 FROM "app"."files" x WHERE x."id" = m."id");
    PERFORM authz_int.sync_dirty('file', ARRAY['*']);
    RETURN NULL;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    DELETE FROM authz_sync."file__mirror" m USING old_rows o WHERE m."id" = o."id";
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    INSERT INTO authz_sync."file__mirror" SELECT mr.* FROM new_rows n CROSS JOIN LATERAL pg_catalog.jsonb_populate_record(NULL::authz_sync."file__mirror", pg_catalog.to_jsonb(n.*) || pg_catalog.jsonb_build_object('readers', (SELECT coalesce(pg_catalog.json_agg(r.key ORDER BY r.key), '[]')::text FROM authz_sync."file__readers" r WHERE r."id" = n."id"))) mr;
  END IF;
  RETURN NULL;
END $f$;

