  authz.login_jwt(text),
  authz.view_as(text, text),
  authz.request_access(text, text, text, text, interval),
  authz.pending_requests(),
  authz.decide_request(bigint, boolean, text),
  authz.cancel_request(bigint),
  authz.break_glass(text, text, text, text, interval),
  authz.start_review(text, text, timestamptz),
  authz.review_items(bigint),
  authz.review_decide(bigint, integer, boolean),
  authz.close_review(bigint, boolean),
  authz.who(text, integer, text),
  authz.explain(text, integer, text, text),
  authz.list_shares(text, integer),
  authz.list_links(text, integer),
  authz.revoke_link(text, integer, text),
  authz.create_link(text, integer, text, timestamptz),
  authz.create_role(text, integer, text, text, text[]),
  authz.roles_of(text, integer),
  authz.request_access(text, integer, text, text, interval),
  authz.break_glass(text, integer, text, text, interval),
  authz.start_review(text, integer, timestamptz),
  authz.can(text, integer, text),
  authz.who_among(text, integer, text, text[], text),
  authz.perms(text, integer),
  authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, text, text, text, integer, text),
  authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, integer, text, text, text, text),
  authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, integer, text, text, integer, text)
  TO "conf_app";

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int', 'authz_sync'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."users"', '"app"."teams"', '"app"."team_members"', '"app"."folders"', '"app"."folder_teams"', '"app"."files"', '"app"."notes"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The PowerSync suite's policy (the Electric suite's): folders inside folders, given to teams (and the teams inside
-- them), files in folders, shares on both, a confidential flag that keeps a file from those who read it only through
-- its folder, and notes on files whose body only their editors read. PowerSync syncs the files, the folders and the
-- notes, from their mirrors (mirrored: each row, but the masked body, with its readers), a bucket for each key.

app role conf_app
sync role conf_ps

type user = app.users(id integer)

type team = app.teams(id integer)
  member : user        = app.team_members(team_id -> user_id)
  member : team#member = app.teams(parent_id -> id)  -- the members of the teams inside it

type folder = app.folders(id integer)
  parent : folder      = parent_id
  owner  : user        = owner_id
  team   : team#member = app.folder_teams(folder_id -> team_id)
  viewer : user shared by edit

  can edit = owner or parent.edit
  can view = edit or team or viewer or parent.view

type file = app.files(id integer)
  folder : folder = folder_id
  owner  : user   = owner_id
  viewer : user shared by edit

  can edit = owner or folder.edit
  can view = edit or viewer or (folder.view and not {confidential})

type note = app.notes(id integer)
  file   : file = file_id
  author : user = author_id

  can edit = author or file.edit
  can view = file.view

rules app.folders
  select                 : view
  update                 : edit
  update parent_id after : parent.edit

rules app.files
  select          : view
  insert          : folder.edit and owner
  update          : edit
  update owner_id : nobody

rules app.notes view app.notes_visible
  select    : view
  mask body : edit

sync app.files : view mirrored
sync app.folders mirrored
sync app.notes mirrored
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+8ca23850ea2d', 'f4e8f3b5e5c4ed9f');

-- the session made read-only above (its statements committed one by one) is as it was again
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_migration.read_only', true) <> '' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', pg_catalog.current_setting('authz_migration.read_only'), false);
    PERFORM pg_catalog.set_config('authz_migration.read_only', '', false);
  END IF;
END $authz_tx$;
